    msg = entry.get('message', {})
    role = msg.get('role', '')
    content = msg.get('content', [])

    text_parts = []
    for c in content:
        if isinstance(c, dict):
            if c.get('type') == 'text':
                text_parts.append(c.get('text', ''))
            elif c.get('type') == 'toolResult':
                details = c.get('details', {})
                status = details.get('status', 'unknown')
                text_parts.append(f"[{status}]")

    full_text = ''.join(text_parts)
    print(f"{role.upper()}: {full_text[:500]}")
    if role == 'assistant':
        # Check for grid output
        if 'grid' in str(content).lower():
            try:
                import re
                match = re.search(r'\{"action": "submit", "grid": (\[[^\]]+\])\}', str(content))
                if match:
                    print("  Grid submitted successfully")
            except:
                pass
